def transform(grid):
    R, C = len(grid), len(grid[0])
    cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    panel = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    # Rotate the panel clockwise.
    out = [list(row) for row in zip(*panel[::-1])]

    # External single-cell markers specify the colors used for the three
    # colored corner/edge markers in the panel.
    outside = {}
    for r in range(R):
        for c in range(C):
            if not (r0 <= r <= r1 and c0 <= c <= c1) and grid[r][c] != 0:
                outside.setdefault(grid[r][c], []).append((r, c))
    return out
